import { clamp } from '@genshin-optimizer/common/util'
import type {
  ArtifactRarity,
  MainStatKey,
  SubstatKey,
} from '@genshin-optimizer/gi/consts'
import {
  artMaxLevel,
  artSlotMainKeys,
  artSubstatRollData,
  charKeyToLocCharKey,
} from '@genshin-optimizer/gi/consts'
import type { IArtifact, IGOOD, ISubstat } from '@genshin-optimizer/gi/good'
import { parseArtifact, substatSchema } from '@genshin-optimizer/gi/good'
import { allStats } from '@genshin-optimizer/gi/stats'
import {
  getMainStatDisplayValue,
  getSubstatRange,
  getSubstatRolls,
  getSubstatValue,
} from '@genshin-optimizer/gi/util'
import type { ArtCharDatabase } from '../ArtCharDatabase'
import { DataManager } from '../DataManager'
import type { IGO, ImportResult } from '../exim'

export interface ICachedArtifact extends IArtifact {
  id: string
  mainStatVal: number
  substats: ICachedSubstat[]
  unactivatedSubstats: ICachedSubstat[] | undefined
}

export interface ICachedSubstat extends ISubstat {
  rolls: number[]
  efficiency: number
  accurateValue: number
}

const statMap = {
  hp: 'HP',
  hp_: 'HP',
  atk: 'ATK',
  atk_: 'ATK',
  def: 'DEF',
  def_: 'DEF',
  eleMas: 'Elemental Mastery',
  enerRech_: 'Energy Recharge',
  critRate_: 'Crit Rate',
  critDMG_: 'Crit DMG',
  heal_: 'Healing Bonus',
} as const

export class ArtifactDataManager extends DataManager<
  string,
  'artifacts',
  ICachedArtifact,
  IArtifact,
  ArtCharDatabase
> {
  constructor(database: ArtCharDatabase) {
    super(database, 'artifacts')
    for (const key of this.database.storage.keys)
      if (key.startsWith('artifact_') && !this.set(key, {}))
        this.database.storage.remove(key)
  }
  override validate(obj: unknown): IArtifact | undefined {
    return validateArtifact(obj)
  }
  override toCache(
    storageObj: IArtifact,
    id: string
  ): ICachedArtifact | undefined {
    // Generate cache fields
    const newArt = cachedArtifact(storageObj, id).artifact

    // Check relations and update equipment
    const oldArt = super.get(id)
    if (newArt.location !== oldArt?.location) {
      const slotKey = newArt.slotKey
      const prevChar = oldArt?.location
        ? this.database.chars.getWithInitWeapon(
            this.database.chars.LocationToCharacterKey(oldArt.location)
          )
        : undefined
      const newChar = newArt.location
        ? this.database.chars.getWithInitWeapon(
            this.database.chars.LocationToCharacterKey(newArt.location)
          )
        : undefined

      // previously equipped art at new location
      const prevArt = super.get(newChar?.equippedArtifacts[slotKey])

      //current prevArt <-> newChar  && newArt <-> prevChar
      //swap to prevArt <-> prevChar && newArt <-> newChar(outside of this if)

      if (prevArt)
        super.setCached(prevArt.id, {
          ...prevArt,
          location: prevChar?.key ? charKeyToLocCharKey(prevChar.key) : '',
        })
      if (newChar)
        this.database.chars.setEquippedArtifact(
          charKeyToLocCharKey(newChar.key),
          slotKey,
          newArt.id
        )
      if (prevChar)
        this.database.chars.setEquippedArtifact(
          charKeyToLocCharKey(prevChar.key),
          slotKey,
          prevArt?.id ?? ''
        )
    } else
      newArt.location &&
        this.database.chars.triggerCharacter(newArt.location, 'update')
    return newArt
  }
  override deCache(artifact: ICachedArtifact): IArtifact {
    const {
      setKey,
      rarity,
      level,
      slotKey,
      mainStatKey,
      substats,
      totalRolls,
      astralMark,
      elixirCrafted,
      location,
      lock,
      unactivatedSubstats,
    } = artifact
    return {
      setKey,
      rarity,
      level,
      slotKey,
      mainStatKey,
      substats: substats.map((substat) => ({
        key: substat.key,
        value: substat.value,
        initialValue: substat.initialValue,
      })),
      totalRolls,
      astralMark,
      elixirCrafted,
      location,
      lock,
      unactivatedSubstats: unactivatedSubstats?.map((substat) => ({
        key: substat.key,
        value: substat.value,
        initialValue: substat.initialValue,
      })),
    }
  }

  new(value: IArtifact): string {
    const id = this.generateKey()
    this.set(id, value)
    return id
  }
  override remove(key: string, notify?: boolean): ICachedArtifact | undefined {
    const art = super.remove(key, notify)
    if (art)
      art.location &&
        this.database.chars.setEquippedArtifact(art.location, art.slotKey, '')
    return art
  }
  override clear(): void {
    super.clear()
  }
  override importGOOD(good: IGOOD & IGO, result: ImportResult) {
    result.artifacts.beforeMerge = this.values.length

    // Match artifacts for counter, metadata, and locations
    const artifacts = good.artifacts

    if (!Array.isArray(artifacts) || !artifacts.length) {
      result.artifacts.notInImport = this.values.length
      return
    }

    const takenIds = new Set(this.keys)
    artifacts.forEach((a) => {
      const id = (a as ICachedArtifact).id
      if (!id) return
      takenIds.add(id)
    })

    result.artifacts.import = artifacts.length
    const idsToRemove = new Set(this.values.map((a) => a.id))
    const hasEquipment = artifacts.some((a) => a.location)
    const hasLock = artifacts.some((a) => a.lock)
    artifacts.forEach((a): void => {
      const art = this.validate(a)
      if (!art) {
        result.artifacts.invalid.push(a)
        return
      }

      let importArt = art
      let importId: string | undefined = (a as ICachedArtifact).id
      let foundDupOrUpgrade = false
      if (!result.ignoreDups) {
        const { duplicated, upgraded } = this.findDups(
          art,
          Array.from(idsToRemove)
        )
        if (duplicated[0] || upgraded[0]) {
          foundDupOrUpgrade = true
          // Favor upgrades with the same location, else use 1st dupe
          let [match, isUpgrade] =
            hasEquipment &&
            art.location &&
            upgraded[0]?.location === art.location
              ? [upgraded[0], true]
              : duplicated[0]
                ? [duplicated[0], false]
                : [upgraded[0], true]
          if (importId) {
            // favor exact id matches
            const up = upgraded.find((a) => a.id === importId)
            if (up) [match, isUpgrade] = [up, true]
            const dup = duplicated.find((a) => a.id === importId)
            if (dup) [match, isUpgrade] = [dup, false]
          }
          isUpgrade
            ? result.artifacts.upgraded.push(art)
            : result.artifacts.unchanged.push(art)
          idsToRemove.delete(match.id)

          //Imported artifact will be set to `importId` later, so remove the dup/upgrade now to avoid a duplicate
          this.remove(match.id, false) // Do not notify, since this is a "replacement"
          if (!importId) importId = match.id // always resolve some id
          importArt = {
            ...art,
            location: hasEquipment ? art.location : match.location,
            // Preserve existing lock state for artifacts reported as unlocked or when the scanner doesn't detect locks ("lock": false JSON)
            lock: hasLock ? art.lock : match.lock,
          }
        }
      }
      if (importId) {
        if (this.get(importId)) {
          // `importid` already in use, get a new id
          const newId = this.generateKey(takenIds)
          takenIds.add(newId)
          if (this.changeId(importId, newId)) {
            // Sync the id in `idsToRemove` due to the `changeId`
            if (idsToRemove.has(importId)) {
              idsToRemove.delete(importId)
              idsToRemove.add(newId)
            }
          }
        }
      } else {
        importId = this.generateKey(takenIds)
        takenIds.add(importId)
      }
      this.set(importId, importArt, !foundDupOrUpgrade)
    })
    const idtoRemoveArr = Array.from(idsToRemove)
    if (result.keepWepArtiNotInImport || result.ignoreDups)
      result.artifacts.notInImport = idtoRemoveArr.length
    else idtoRemoveArr.forEach((k) => this.remove(k))

    this.database.weapons.ensureEquipments()
  }
  findDups(
    editorArt: IArtifact,
    idList = this.keys
  ): { duplicated: ICachedArtifact[]; upgraded: ICachedArtifact[] } {
    const { setKey, rarity, level, slotKey, mainStatKey, substats } = editorArt

    const arts = idList
      .map((id) => this.get(id))
      .filter((a) => a) as ICachedArtifact[]
    const candidates = arts.filter(
      (candidate) =>
        setKey === candidate.setKey &&
        rarity === candidate.rarity &&
        slotKey === candidate.slotKey &&
        mainStatKey === candidate.mainStatKey &&
        level >= candidate.level &&
        substats.every(
          (substat, i) =>
            !candidate.substats[i].key || // Candidate doesn't have anything on this slot
            (substat.key === candidate.substats[i].key && // Or editor simply has better substat
              substat.value >= candidate.substats[i].value)
        )
    )

    // Strictly upgraded artifact
    const upgraded = candidates
      .filter(
        (candidate) =>
          level > candidate.level &&
          (Math.floor(level / 4) === Math.floor(candidate.level / 4) // Check for extra rolls
            ? substats.every(
                (
                  substat,
                  i // Has no extra roll
                ) =>
                  substat.key === candidate.substats[i].key &&
                  substat.value === candidate.substats[i].value
              )
            : substats.some(
                (
                  substat,
                  i // Has extra rolls
                ) =>
                  candidate.substats[i].key
                    ? substat.value > candidate.substats[i].value // Extra roll to existing substat
                    : substat.key // Extra roll to new substat
              ))
      )
      .sort((candidates) =>
        candidates.location === editorArt.location ? -1 : 1
      )
    // Strictly duplicated artifact
    const duplicated = candidates
      .filter(
        (candidate) =>
          level === candidate.level &&
          substats.every(
            (substat) =>
              !substat.key || // Empty slot
              candidate.substats.some(
                (candidateSubstat) =>
                  substat.key === candidateSubstat.key && // Or same slot
                  substat.value === candidateSubstat.value
              )
          )
      )
      .sort((candidates) =>
        candidates.location === editorArt.location ? -1 : 1
      )
    return { duplicated, upgraded }
  }
}

export function cachedArtifact(
  flex: IArtifact,
  id: string
): { artifact: ICachedArtifact; errors: string[] } {
  const {
    location,
    lock,
    setKey,
    slotKey,
    rarity,
    mainStatKey,
    totalRolls,
    astralMark,
    elixirCrafted,
  } = flex
  const level = Math.round(
    Math.min(Math.max(0, flex.level), rarity >= 3 ? rarity * 4 : 4)
  )
  const mainStatVal = getMainStatDisplayValue(mainStatKey, rarity, level)
  let unactivatedSubstats: ICachedSubstat[] | undefined =
    flex.unactivatedSubstats?.map((substat) => ({
      ...substat,
      rolls: [],
      efficiency: 0,
      accurateValue: substat.value,
    }))

  const errors: string[] = []
  const substats: ICachedSubstat[] = flex.substats.map((substat) => ({
    ...substat,
    rolls: [],
    efficiency: 0,
    accurateValue: substat.value,
  }))
  const validated: ICachedArtifact = {
    id,
    setKey,
    location,
    slotKey,
    lock,
    mainStatKey,
    rarity,
    level,
    substats,
    totalRolls,
    astralMark,
    elixirCrafted,
    mainStatVal,
    unactivatedSubstats,
  }

  const allPossibleRolls: { index: number; substatRolls: number[][] }[] = []
  let totalUnambiguousRolls = 0

  function efficiency(value: number, key: SubstatKey): number {
    return value / getSubstatValue(key)
  }

  const getSubstatEffRoll = (substats: ICachedSubstat[] | undefined) => {
    substats?.forEach((substat, index): void => {
      const { key, value } = substat
      if (!key) {
        substat.value = 0
        return
      }
      substat.efficiency = efficiency(value, key)

      let possibleRolls = getSubstatRolls(key, value, rarity)
      // Pin the recorded initial roll as the first roll. If the initial value can't
      // be applied to the current value (e.g. the value was just edited and `initialValue`
      // hasn't been reconciled yet), fall back to any assumed decomposition.
      if (substat.initialValue !== undefined && possibleRolls.length) {
        const accurateValue = possibleRolls[0].reduce((a, b) => a + b, 0)
        const ivAccurateValue = getSubstatRolls(
          key,
          substat.initialValue,
          rarity
        )[0]?.[0]
        const lookupValue =
          ivAccurateValue !== undefined ? accurateValue - ivAccurateValue : 0

        if (ivAccurateValue !== undefined && lookupValue > 1e-3) {
          const remainingRolls = getSubstatRolls(key, lookupValue, rarity)
          if (remainingRolls.length)
            possibleRolls = remainingRolls.map((roll) => [
              ivAccurateValue,
              ...roll,
            ])
        }
      }

      if (possibleRolls.length) {
        // Valid Substat
        const possibleLengths = new Set(
          possibleRolls.map((roll) => roll.length)
        )

        if (possibleLengths.size !== 1) {
          // Ambiguous Rolls
          allPossibleRolls.push({ index, substatRolls: possibleRolls })
        } else {
          // Unambiguous Rolls
          totalUnambiguousRolls += possibleRolls[0].length
        }

        substat.rolls = possibleRolls.reduce((best, current) =>
          best.length < current.length ? best : current
        )
        substat.efficiency = efficiency(
          substat.rolls.reduce((a: number, b: number) => a + b, 0),
          key
        )
        substat.accurateValue = substat.rolls.reduce(
          (a: number, b: number) => a + b,
          0
        )
      } else {
        // Invalid Substat
        substat.rolls = []
        errors.push(
          `Invalid substat ${
            statMap[substat.key as keyof typeof statMap] ?? substat.key
          }`
        )
      }
    })
  }

  getSubstatEffRoll(substats)
  getSubstatEffRoll(unactivatedSubstats)

  if (errors.length) return { artifact: validated, errors }

  const { low, high } = artSubstatRollData[rarity],
    lowerBound = low + Math.floor(level / 4),
    upperBound = high + Math.floor(level / 4)

  let highestScore = Number.NEGATIVE_INFINITY // -Max(substats.rolls[i].length) over ambiguous rolls
  const tryAllSubstats = (
    rolls: { index: number; roll: number[] }[],
    currentScore: number,
    total: number
  ) => {
    if (rolls.length === allPossibleRolls.length) {
      const [searchLower, searchUpper] =
        totalRolls !== undefined
          ? [totalRolls, totalRolls]
          : [lowerBound, upperBound]

      if (
        total <= searchUpper &&
        total >= searchLower &&
        highestScore < currentScore
      ) {
        highestScore = currentScore
        for (const { index, roll } of rolls) {
          const key = substats[index].key as SubstatKey
          const accurateValue = roll.reduce((a, b) => a + b, 0)
          substats[index].rolls = roll
          substats[index].accurateValue = accurateValue
          substats[index].efficiency = efficiency(accurateValue, key)
        }
      }

      return
    }

    const { index, substatRolls } = allPossibleRolls[rolls.length]
    for (const roll of substatRolls) {
      rolls.push({ index, roll })
      const newScore = Math.min(currentScore, -roll.length)
      if (newScore >= highestScore)
        // Scores won't get better, so we can skip.
        tryAllSubstats(rolls, newScore, total + roll.length)
      rolls.pop()
    }
  }

  tryAllSubstats([], Number.POSITIVE_INFINITY, totalUnambiguousRolls)

  if (substats[3].rolls.length && unactivatedSubstats?.length) {
    validated.unactivatedSubstats = []
    unactivatedSubstats = []
  }

  const artifactRolls = substats.reduce(
    (accu, { rolls }) => accu + rolls.length,
    0
  )

  if (artifactRolls > upperBound)
    errors.push(
      `${rarity}-star artifact (level ${level}) should have no more than ${upperBound} rolls. It currently has ${artifactRolls} rolls.`
    )
  else if (artifactRolls < lowerBound)
    errors.push(
      `${rarity}-star artifact (level ${level}) should have at least ${lowerBound} rolls. It currently has ${artifactRolls} rolls.`
    )

  if (substats.some((substat) => !substat.key)) {
    const substat = substats.find((substat) => (substat.rolls?.length ?? 0) > 1)
    if (substat)
      errors.push(
        `Substat ${
          statMap[substat.key as keyof typeof statMap] ?? substat.key
        } has > 1 roll, but not all substats are unlocked.`
      )
  }

  return { artifact: validated, errors }
}

function defSub(): ISubstat {
  return { key: '', value: 0 }
}

function parseSubstats(
  obj: unknown,
  rarity: ArtifactRarity,
  allowZeroSub = false
): ISubstat[] {
  if (!obj || !Array.isArray(obj)) {
    return Array.from({ length: 4 }, () => defSub())
  }

  const substats = obj.slice(0, 4).map((item): ISubstat => {
    const result = substatSchema.safeParse(item)
    if (!result.success) return defSub()

    const { key, value: rawValue, initialValue } = result.data

    if (!key) return { key: '', value: 0 }

    let value = key.endsWith('_')
      ? Math.round(rawValue * 10) / 10
      : Math.round(rawValue)

    const { low, high } = getSubstatRange(rarity, key as SubstatKey)
    value = clamp(value, allowZeroSub ? 0 : low, high)

    return initialValue !== undefined
      ? { key, value, initialValue }
      : { key, value }
  })

  while (substats.length < 4) substats.push(defSub())

  return substats
}

export function validateArtifact(
  obj: unknown,
  allowZeroSub = false
): IArtifact | undefined {
  const parsed = parseArtifact(obj)
  if (!parsed) return undefined

  const {
    setKey,
    rarity,
    slotKey,
    substats,
    unactivatedSubstats,
    totalRolls,
    astralMark,
    elixirCrafted,
    location,
    lock,
  } = parsed
  let { mainStatKey } = parsed

  // set/slot/rarity compatibility (needs allStats)
  const setData = allStats.art.data[setKey]
  if (!setData) return undefined
  if (!setData.slots.includes(slotKey)) return undefined
  if (!setData.rarities.includes(rarity)) return undefined

  // level capped by rarity (check raw input)
  const rawLevel = (obj as { level?: unknown }).level
  if (typeof rawLevel !== 'number' || rawLevel < 0) return undefined
  const level = Math.round(rawLevel)
  if (level > artMaxLevel[rarity]) return undefined

  // substat can't match mainstat
  const parsedSubstats = parseSubstats(substats, rarity, allowZeroSub)
  const parsedUnactivated = parseSubstats(
    unactivatedSubstats,
    rarity,
    allowZeroSub
  )
  if (
    parsedSubstats.find((sub) => sub.key === mainStatKey) ||
    parsedUnactivated.find((sub) => sub.key === mainStatKey)
  )
    return undefined

  // mainstat must be valid for slot
  const plausibleMainStats = artSlotMainKeys[slotKey]
  if (!(plausibleMainStats as unknown as MainStatKey[]).includes(mainStatKey))
    if (plausibleMainStats.length === 1) mainStatKey = plausibleMainStats[0]
    else return undefined

  // move unactivated to slot 4 if level >= 4
  let finalUnactivated: ISubstat[] | undefined = parsedUnactivated.length
    ? parsedUnactivated
    : undefined
  if (level >= 4 && !parsedSubstats[3].key && parsedUnactivated[0]) {
    parsedSubstats[3] = parsedUnactivated[0]
    finalUnactivated = []
  }

  return {
    setKey,
    rarity,
    level,
    slotKey,
    mainStatKey,
    substats: parsedSubstats,
    totalRolls,
    astralMark,
    elixirCrafted,
    location,
    lock,
    unactivatedSubstats: finalUnactivated,
  }
}
